:root {
  color-scheme: light;
  --canvas: var(--sya-canvas, #eef1ed);
  --surface: var(--sya-surface, #fcfdfb);
  --surface-muted: var(--sya-surface-muted, #e2e6e1);
  --text: var(--sya-text, #191b19);
  --text-secondary: var(--sya-text-secondary, #59605b);
  --border: var(--sya-border, #d9ddd9);
  --primary: var(--sya-primary, #252725);
  --primary-hover: var(--sya-primary-hover, #343734);
  --primary-foreground: var(--sya-primary-foreground, #f8faf8);
  --success: var(--sya-success, #18794e);
  --success-foreground: var(--sya-success-foreground, #ffffff);
  --success-surface: var(--sya-success-surface, #e7f6ec);
  --success-surface-foreground: var(--sya-success-surface-foreground, #17653f);
  --warning: var(--sya-warning, #946200);
  --warning-foreground: var(--sya-warning-foreground, #ffffff);
  --warning-surface: var(--sya-warning-surface, #fff3d6);
  --warning-surface-foreground: var(--sya-warning-surface-foreground, #6b4600);
  --danger: var(--sya-danger, #b42318);
  --danger-foreground: var(--sya-danger-foreground, #ffffff);
  --danger-surface: var(--sya-danger-surface, #fce8e6);
  --danger-surface-foreground: var(--sya-danger-surface-foreground, #8f1d14);
  --focus: var(--sya-focus, #3f6652);
  --radius-surface: 18px;
  --shadow-resting: 0 1px 2px rgb(20 28 23 / 5%), 0 10px 30px rgb(20 28 23 / 6%);
  --shadow-floating: 0 4px 12px rgb(20 28 23 / 8%), 0 24px 48px rgb(20 28 23 / 12%);
  --duration-fast: 160ms;
  --duration-standard: 280ms;
  --ease-standard: cubic-bezier(0.22, 1, 0.36, 1);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) {
    color-scheme: dark;
    --canvas: var(--sya-canvas, #121412);
    --surface: var(--sya-surface, #1a1d1a);
    --surface-muted: var(--sya-surface-muted, #232623);
    --text: var(--sya-text, #f1f3f0);
    --text-secondary: var(--sya-text-secondary, #afb5b0);
    --border: var(--sya-border, #373b37);
    --primary: var(--sya-primary, #ecefeb);
    --primary-hover: var(--sya-primary-hover, #ffffff);
    --primary-foreground: var(--sya-primary-foreground, #1b1d1b);
    --success: var(--sya-success, #62c98f);
    --success-foreground: var(--sya-success-foreground, #092416);
    --success-surface: var(--sya-success-surface, #173526);
    --success-surface-foreground: var(--sya-success-surface-foreground, #8ee0ae);
    --warning: var(--sya-warning, #e9ad45);
    --warning-foreground: var(--sya-warning-foreground, #291900);
    --warning-surface: var(--sya-warning-surface, #3b2b12);
    --warning-surface-foreground: var(--sya-warning-surface-foreground, #f2c66f);
    --danger: var(--sya-danger, #ff716b);
    --danger-foreground: var(--sya-danger-foreground, #260503);
    --danger-surface: var(--sya-danger-surface, #3d1d1c);
    --danger-surface-foreground: var(--sya-danger-surface-foreground, #ffaaa5);
    --focus: var(--sya-focus, #93b7a2);
    --shadow-resting: 0 1px 2px rgb(0 0 0 / 20%), 0 14px 34px rgb(0 0 0 / 22%);
    --shadow-floating: 0 6px 16px rgb(0 0 0 / 32%), 0 28px 56px rgb(0 0 0 / 40%);
  }
}

html[data-theme="light"] {
  color-scheme: light;
}

html[data-theme="dark"] {
  color-scheme: dark;
  --canvas: var(--sya-canvas, #121412);
  --surface: var(--sya-surface, #1a1d1a);
  --surface-muted: var(--sya-surface-muted, #232623);
  --text: var(--sya-text, #f1f3f0);
  --text-secondary: var(--sya-text-secondary, #afb5b0);
  --border: var(--sya-border, #373b37);
  --primary: var(--sya-primary, #ecefeb);
  --primary-hover: var(--sya-primary-hover, #ffffff);
  --primary-foreground: var(--sya-primary-foreground, #1b1d1b);
  --success: var(--sya-success, #62c98f);
  --success-foreground: var(--sya-success-foreground, #092416);
  --success-surface: var(--sya-success-surface, #173526);
  --success-surface-foreground: var(--sya-success-surface-foreground, #8ee0ae);
  --warning: var(--sya-warning, #e9ad45);
  --warning-foreground: var(--sya-warning-foreground, #291900);
  --warning-surface: var(--sya-warning-surface, #3b2b12);
  --warning-surface-foreground: var(--sya-warning-surface-foreground, #f2c66f);
  --danger: var(--sya-danger, #ff716b);
  --danger-foreground: var(--sya-danger-foreground, #260503);
  --danger-surface: var(--sya-danger-surface, #3d1d1c);
  --danger-surface-foreground: var(--sya-danger-surface-foreground, #ffaaa5);
  --focus: var(--sya-focus, #93b7a2);
  --shadow-resting: 0 1px 2px rgb(0 0 0 / 20%), 0 14px 34px rgb(0 0 0 / 22%);
  --shadow-floating: 0 6px 16px rgb(0 0 0 / 32%), 0 28px 56px rgb(0 0 0 / 40%);
}

::selection {
  background: color-mix(in srgb, var(--focus) 24%, transparent);
}

html[data-theme="dark"] .sya-code-source .shiki,
html[data-theme="dark"] .sya-code-source .shiki span {
  color: var(--shiki-dark) !important;
}

@media (prefers-color-scheme: dark) {
  html:not([data-theme="light"]) .sya-code-source .shiki,
  html:not([data-theme="light"]) .sya-code-source .shiki span {
    color: var(--shiki-dark) !important;
  }
}

@keyframes sya-input-value-error-feedback {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-4px); }
  50% { transform: translateX(3px); }
  75% { transform: translateX(-2px); }
}

@keyframes sya-input-value-error-feedback-reduced {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.55; }
}

@keyframes sya-input-character-reveal {
  from { opacity: 0; transform: translateY(100%); }
  to { opacity: 1; transform: translateY(0%); }
}

export const motionTokens = {
  duration: {
    instant: 0.12,
    fast: 0.16,
    standard: 0.24,
    considered: 0.48,
    reveal: 0.6,
    lineReveal: 0.86,
  },
  ease: {
    enter: [0.16, 1, 0.3, 1],
    standard: [0.22, 1, 0.36, 1],
  },
  spring: {
    snappy: { type: "spring", visualDuration: 0.26, bounce: 0.12 },
    smooth: { type: "spring", visualDuration: 0.4, bounce: 0 },
    morph: { type: "spring", visualDuration: 0.42, bounce: 0.16 },
  },
  stagger: { item: 0.035, character: 0.025, word: 0.075, line: 0.08 },
  blur: { subtle: 2 },
} as const;

"use client";

import {
  forwardRef,
  useId,
  useState,
  type ComponentPropsWithoutRef,
  type ReactNode,
} from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { motionTokens } from "../lib/motion-tokens";
import "../foundation.css";

export type TooltipVariant = "filled" | "bordered";
export type TooltipSize = "small" | "medium" | "large";
export type TooltipSide = "top" | "right" | "bottom" | "left";

export interface TooltipProps extends Omit<ComponentPropsWithoutRef<"button">, "children" | "content"> {
  /** Accessible name announced for the icon trigger. */
  "aria-label": string;
  /** Content displayed in the tooltip. */
  content: ReactNode;
  /** Visible trigger icon. */
  icon: ReactNode;
  variant?: TooltipVariant;
  size?: TooltipSize;
  side?: TooltipSide;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
}

const triggerSizeClass: Record<TooltipSize, string> = {
  small: "size-8 [&>svg]:size-[14px]",
  medium: "size-[46px] [&>svg]:size-[18px]",
  large: "size-[52px] [&>svg]:size-5",
};

const triggerAppearanceClass: Record<TooltipVariant, string> = {
  filled: "border-transparent bg-[var(--surface-muted)] text-[var(--text-secondary)] hover:bg-[color-mix(in_srgb,var(--surface-muted)_82%,var(--text))] hover:text-[var(--text)]",
  bordered: "border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-muted)_58%,var(--surface))] text-[var(--text-secondary)] hover:border-[var(--text-secondary)] hover:bg-[var(--surface-muted)] hover:text-[var(--text)]",
};

const panelPositionClass: Record<TooltipSide, string> = {
  top: "bottom-full left-1/2 mb-2 -translate-x-1/2 origin-bottom",
  right: "top-1/2 left-full ml-2 -translate-y-1/2 origin-left",
  bottom: "top-full left-1/2 mt-2 -translate-x-1/2 origin-top",
  left: "top-1/2 right-full mr-2 -translate-y-1/2 origin-right",
};

export const Tooltip = forwardRef<HTMLButtonElement, TooltipProps>(function Tooltip({
  content,
  icon,
  variant = "filled",
  size = "medium",
  side = "top",
  open,
  defaultOpen = false,
  onOpenChange,
  className,
  disabled,
  onPointerEnter,
  onPointerLeave,
  onFocus,
  onBlur,
  onKeyDown,
  ...props
}, ref) {
  const tooltipId = useId();
  const reduceMotion = useReducedMotion() ?? false;
  const [internalOpen, setInternalOpen] = useState(defaultOpen);
  const isOpen = open ?? internalOpen;

  const setOpen = (nextOpen: boolean) => {
    if (open === undefined) setInternalOpen(nextOpen);
    onOpenChange?.(nextOpen);
  };

  return (
    <span className="relative inline-flex">
      <button
        {...props}
        ref={ref}
        type={props.type ?? "button"}
        disabled={disabled}
        className={[
          "inline-grid shrink-0 place-items-center rounded-full border transition-[background-color,border-color,color,transform] duration-[var(--duration-fast)] ease-[var(--ease-standard)] [webkit-tap-highlight-color:transparent] focus-visible:outline-2 focus-visible:outline-[var(--focus)] focus-visible:outline-offset-3 disabled:cursor-not-allowed disabled:opacity-[0.48] active:not-disabled:translate-y-px",
          triggerSizeClass[size],
          triggerAppearanceClass[variant],
          className,
        ].filter(Boolean).join(" ")}
        aria-describedby={isOpen ? tooltipId : undefined}
        onPointerEnter={(event) => {
          onPointerEnter?.(event);
          if (!event.defaultPrevented && !disabled) setOpen(true);
        }}
        onPointerLeave={(event) => {
          onPointerLeave?.(event);
          if (!event.defaultPrevented) setOpen(false);
        }}
        onFocus={(event) => {
          onFocus?.(event);
          if (!event.defaultPrevented && !disabled) setOpen(true);
        }}
        onBlur={(event) => {
          onBlur?.(event);
          if (!event.defaultPrevented) setOpen(false);
        }}
        onKeyDown={(event) => {
          onKeyDown?.(event);
          if (!event.defaultPrevented && event.key === "Escape") {
            setOpen(false);
            event.currentTarget.blur();
          }
        }}
      >
        <span className="grid place-items-center" aria-hidden="true">{icon}</span>
      </button>
      <AnimatePresence>
        {isOpen ? (
          <span className={["pointer-events-none absolute z-50", panelPositionClass[side]].join(" ")}>
            <motion.span
              className="block w-max max-w-64 rounded-[10px] bg-[var(--text)] px-2.5 py-1.5 text-xs leading-[1.35] font-[560] text-[var(--surface)] shadow-[var(--shadow-floating)]"
              id={tooltipId}
              role="tooltip"
              initial={reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.92, y: side === "top" ? 3 : side === "bottom" ? -3 : 0, x: side === "left" ? 3 : side === "right" ? -3 : 0 }}
              animate={{ opacity: 1, scale: 1, x: 0, y: 0 }}
              exit={reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.96 }}
              transition={reduceMotion ? { duration: 0.01 } : motionTokens.spring.smooth}
            >
              {content}
            </motion.span>
          </span>
        ) : null}
      </AnimatePresence>
    </span>
  );
});
